(() => {if(location.pathname!=='/')return;document.body.classList.add('arena-admin');const target=document.createElement('div');target.innerHTML="<section class=\"arena\" data-arena data-api=\"/api/client/\">\n <header class=\"arena-head\"><div><p class=\"arena-kicker\">MEKODATACTF / ATTACK &amp; DEFENSE</p><h1>Live arena</h1></div><span data-live role=\"status\">\u0110ang k\u1ebft n\u1ed1i\u2026</span></header>\n <div class=\"arena-meta\"><span data-phase>\u2014</span><span data-tick>Round \u2014 / Tick \u2014</span><strong data-timer>\u2014</strong></div>\n <progress data-progress value=\"0\" max=\"120\" aria-label=\"Ti\u1ebfn \u0111\u1ed9 tick\"></progress>\n <p data-updated class=\"arena-note\">Ch\u1edd d\u1eef li\u1ec7u cu\u1ed9c thi.</p>\n <div class=\"arena-board\"><table><caption>B\u1ea3ng x\u1ebfp h\u1ea1ng tr\u1ef1c ti\u1ebfp</caption><thead><tr><th scope=\"col\">H\u1ea1ng</th><th scope=\"col\">\u0110\u1ed9i</th><th scope=\"col\">T\u1ed5ng</th><th scope=\"col\">SLA</th><th scope=\"col\">Attack</th><th scope=\"col\">Defense</th></tr></thead><tbody data-ranking><tr><td colspan=\"6\">\u0110ang t\u1ea3i \u0111i\u1ec3m\u2026</td></tr></tbody></table></div>\n <p class=\"arena-note\">Defense l\u00e0 \u0111i\u1ec3m ph\u1ea1t c\u00f3 th\u1ec3 \u00e2m. Th\u1ee9 h\u1ea1ng b\u1eb1ng \u0111i\u1ec3m \u0111\u01b0\u1ee3c hi\u1ec3n th\u1ecb \u0111\u1ed3ng h\u1ea1ng.</p>\n</section>";document.getElementById('app').before(target);const script=document.createElement('script');script.src='/arena.js';document.body.append(script);})();